SELECT id, source_system, source_object_type, source_object_id, source_object_no, source_revision, tax_scope_key, calculation_stage, supply_kind, business_mode, seller_party_id, buyer_client_id, tax_subject_party_id, acquiring_entity_no, currency, price_mode, tax_point_date, tax_point_basis, status, tax_amount_source, block_reasons_json, net_amount, charged_tax_amount, gross_amount, rounding_amount, expires_at, create_time FROM t_tax_calculation
WHERE source_system = #{sourceSystem} AND source_object_type = #{sourceObjectType} AND source_object_id = #{sourceObjectId}
  AND source_revision = #{sourceRevision} AND tax_scope_key = #{taxScopeKey}
